description:
Write two data structures from scratch.

```java
// MinStack.java: a stack of ints that also reports its minimum, every operation O(1)
class MinStack {
    void push(int x)
    int pop()           // NoSuchElementException when empty
    int peek()
    int min()           // the smallest value currently in the stack
    boolean isEmpty()
}

// IntHashSet.java: a set of ints using an array of buckets with chaining
class IntHashSet {
    boolean add(int x)         // false if already present
    boolean contains(int x)
    boolean remove(int x)      // false if absent
    int size()
    int capacity()             // the number of buckets: starts at 8, doubles when size would exceed 0.75 x capacity
}
```

Use arrays and your own node classes; `java.util` collections are not allowed inside these classes (exceptions are fine). Negative numbers must work in the hash set.

solution.MinStack.java:
import java.util.NoSuchElementException;

class MinStack {
    private int[] values = new int[8];
    private int[] mins = new int[8];
    private int size;

    void push(int x) {
        if (size == values.length) {
            values = java.util.Arrays.copyOf(values, size * 2);
            mins = java.util.Arrays.copyOf(mins, size * 2);
        }
        mins[size] = size == 0 ? x : Math.min(x, mins[size - 1]);
        values[size++] = x;
    }

    int pop() {
        if (size == 0) throw new NoSuchElementException("empty stack");
        return values[--size];
    }

    int peek() {
        if (size == 0) throw new NoSuchElementException("empty stack");
        return values[size - 1];
    }

    int min() {
        if (size == 0) throw new NoSuchElementException("empty stack");
        return mins[size - 1];
    }

    boolean isEmpty() { return size == 0; }
}

solution.IntHashSet.java:
class IntHashSet {
    private static class Node {
        final int value;
        Node next;
        Node(int value, Node next) { this.value = value; this.next = next; }
    }

    private Node[] buckets = new Node[8];
    private int size;

    private static int index(int x, int n) { return Math.floorMod(x, n); }   // an int is its own hash code

    boolean contains(int x) {
        for (Node n = buckets[index(x, buckets.length)]; n != null; n = n.next) if (n.value == x) return true;
        return false;
    }

    boolean add(int x) {
        if (contains(x)) return false;
        if (size + 1 > buckets.length * 3 / 4) resize();
        int i = index(x, buckets.length);
        buckets[i] = new Node(x, buckets[i]);
        size++;
        return true;
    }

    boolean remove(int x) {
        int i = index(x, buckets.length);
        Node prev = null;
        for (Node n = buckets[i]; n != null; prev = n, n = n.next) {
            if (n.value == x) {
                if (prev == null) buckets[i] = n.next; else prev.next = n.next;
                size--;
                return true;
            }
        }
        return false;
    }

    private void resize() {
        Node[] old = buckets;
        buckets = new Node[old.length * 2];
        for (Node head : old) {
            for (Node n = head; n != null; n = n.next) {
                int i = index(n.value, buckets.length);
                buckets[i] = new Node(n.value, buckets[i]);
            }
        }
    }

    int size() { return size; }
    int capacity() { return buckets.length; }
}

unitTests:
test("min stack", () -> {
    MinStack s = new MinStack();
    s.push(5); s.push(3); s.push(7); s.push(3); s.push(1);
    checkEq(s.min(), 1);
    checkEq(s.pop(), 1);
    checkEq(s.min(), 3);
    s.pop();
    checkEq(s.min(), 3);
    s.pop(); s.pop();
    checkEq(s.min(), 5);
    checkEq(s.peek(), 5);
    s.pop();
    checkEq(s.isEmpty(), true);
    checkThrows(NoSuchElementException.class, s::pop);
    checkThrows(NoSuchElementException.class, s::min);
});

test("min stack grows", () -> {
    MinStack s = new MinStack();
    for (int i = 100; i > 0; i--) s.push(i);
    checkEq(s.min(), 1);
    for (int i = 0; i < 50; i++) s.pop();
    checkEq(s.min(), 51);
});

test("hash set basics", () -> {
    IntHashSet set = new IntHashSet();
    checkEq(set.add(5), true);
    checkEq(set.add(5), false);
    checkEq(set.add(-13), true);
    checkEq(set.contains(-13), true);
    checkEq(set.contains(13), false);
    checkEq(set.remove(5), true);
    checkEq(set.remove(5), false);
    checkEq(set.size(), 1);
    checkEq(set.capacity(), 8);
});

test("hash set resizing", () -> {
    IntHashSet set = new IntHashSet();
    for (int i = 0; i < 6; i++) set.add(i * 16);
    checkEq(set.capacity(), 8);
    set.add(1000);
    checkEq(set.capacity(), 16);
    for (int i = 0; i < 10_000; i++) set.add(i * 7 - 5_000);
    check(set.capacity() * 3 / 4 >= set.size(), "the load factor should stay at most 0.75");
    boolean all = true;
    for (int i = 0; i < 10_000; i++) all &= set.contains(i * 7 - 5_000);
    check(all, "every added number should be found");
    checkEq(set.contains(1), false);
});

